import { useState, useEffect } from 'react'
import { PinInputWrapper } from './index.style'
import { CustomText, Container } from '../../../../components'
import { NotificationContainer } from 'react-notifications'
import AuthActions from '../../../../redux/auth/action'
import ErrorActions from '../../../../redux/error/action'
// import OjkFooter from '../../../../components/OjkFooter'
import PinInput from '../../../../components/PinInput'
import { useSelector, useDispatch } from 'react-redux'
import { useUpdateGlobal } from '../../../../state/globalState/hooks/useGlobalContext'
import ShowSnackbar from '../../../../components/ShowNotification'
import { PIN_NEW } from '../../../../images'
import { useHistory } from 'react-router'

function PinContainer({ location }) {
  const [error, setError] = useState(false)
  const crypto = require('crypto')

  const [, dispatchGlobal] = useUpdateGlobal()
  const dispatch = useDispatch()
  const history = useHistory()

  const validatePinLoading = useSelector((state) => state.Loading.VALIDATE_PIN)
  const validatePinError = useSelector((state) => state.Error.VALIDATE_PIN)
  const validatePinStatus = useSelector((state) => state.Auth.validatePinStatus)

  useEffect(() => {
    if (validatePinLoading === false && validatePinError === false) {
      dispatchGlobal({
        globalState: {
          isLoggedIn: true,
        },
      })
      history.push('/dashboard')
    }
    if (validatePinError && validatePinLoading === false) {
      ShowSnackbar.error({
        visible: true,
        text:
          'PIN salah' ||
          validatePinStatus.error_msg ||
          'Request tidak dapat diproses, silahkan coba lagi',
      })
      dispatch(ErrorActions.resetErrorRedux(['VALIDATE_PIN']))
    }
  }, [validatePinLoading, validatePinError, validatePinStatus])

  useEffect(() => {
    return () => {
      clearInterval()
    }
  }, [])

  useEffect(() => {
    if (validatePinStatus.redirect_to_forgot_pin === true) {
      history.push('/reset-pin')
      dispatch(ErrorActions.resetErrorRedux(['VALIDATE_PIN']))
      dispatch(AuthActions.resetAuthStore(['validatePinStatus']))
    }
  }, [validatePinStatus])

  const hashString = (input) => {
    return crypto.createHash('sha256').update(input).digest('hex')
  }

  const handleSubmit = (value) => {
    dispatch(
      AuthActions.validatePin({
        payload: {
          phone_no: location.state.phoneNo,
          pin: hashString(value),
        },
      })
    )
  }

  return (
    <Container
      title=" "
      backBtnColor="#000000"
      bgColor="#f5f5f5"
      onBackClick={() => history.push('/login')}
      showInnerHeader
    >
      <PinInputWrapper location={location.pathname === '/login/pin'}>
        <div className="text-container">
          <div>
            <img src={PIN_NEW} alt="" className="icon" />
          </div>
        </div>
        <CustomText
          size={12}
          weight={700}
          textAlign="center"
          top="20px"
          bottom=""
          color="#000000"
        >
          Masukkan PIN
        </CustomText>
        <CustomText
          size={12}
          weight={500}
          textAlign="center"
          top="20px"
          bottom="8%"
          color="#000000"
        >
          Masukkan 4 digit angka untuk masuk aplikasi
        </CustomText>
        <PinInput onComplete={handleSubmit} error={error} setError={setError} />
        {error && (
          <CustomText
            size={12}
            weight={500}
            textAlign="center"
            top="20px"
            bottom=""
            color="#DC0000"
          >
            PIN salah
          </CustomText>
        )}
        <CustomText
          size={12}
          weight={700}
          textAlign="center"
          top="20px"
          color="#0078FA"
          textDecoration="underline"
          onClick={() => {
            history.push('/forgot-pin')
          }}
        >
          Lupa PIN Anda?
        </CustomText>
        <NotificationContainer />
      </PinInputWrapper>
    </Container>
  )
}

export default PinContainer
